$(function () {
  $(".sidebarMenuScroll").overlayScrollbars({
    scrollbars: {
      visibility: "auto",
      autoHide: "leave",
      autoHideDelay: 200,
      dragScrolling: true,
      clickScrolling: false,
      touchSupport: true,
      snapHandle: false,
    },
  });
});

